using FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.ValueObjects;

namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.Commands;

/// <summary>
///     An alert evaluated by an Edge Gateway. The first reading identifier is the triggering reading. Type and
///     severity are empty when the gateway sent an unknown value, so that one malformed entry does not reject the batch.
/// </summary>
/// <param name="AlertId">The alert identifier generated by the Edge Gateway.</param>
/// <param name="DeviceId">The device that captured the supporting readings.</param>
/// <param name="Type">The alert type, or <see langword="null"/> when missing or unknown.</param>
/// <param name="Severity">The alert severity, or <see langword="null"/> when missing or unknown.</param>
/// <param name="ReadingIds">The supporting readings; the first one triggers the alert.</param>
/// <param name="ConfigurationRevision">The rule revision used to evaluate the alert.</param>
/// <param name="ThresholdMinValue">The lower bound of the evaluated threshold, for threshold alerts.</param>
/// <param name="ThresholdMaxValue">The upper bound of the evaluated threshold, for threshold alerts.</param>
/// <param name="GeofenceId">The geofence that was left, for geofence alerts.</param>
/// <param name="DistanceToBoundaryMeters">The distance to the geofence boundary in meters, for geofence alerts.</param>
public record EdgeAlertEntry(
    Guid AlertId,
    Guid DeviceId,
    AlertType? Type,
    AlertSeverity? Severity,
    IReadOnlyList<Guid> ReadingIds,
    long ConfigurationRevision,
    double? ThresholdMinValue,
    double? ThresholdMaxValue,
    Guid? GeofenceId,
    double? DistanceToBoundaryMeters);
